const aiResponse = $input.item.json.choices[0].message.content;
let qualification;
try {
  qualification = JSON.parse(aiResponse.replace(/```json|```/g, '').trim());
} catch(e) {
  qualification = { status: 'WARM', reason: 'Parse error - manual review needed', next_action: 'Manual follow-up' };
}

return [{
  json: {
    ...qualification,
    lead_id: $('Extract Lead Data').item.json.lead_id,
    lead_name: $('Extract Lead Data').item.json.lead_name,
    lead_phone: $('Extract Lead Data').item.json.lead_phone,
    lead_email: $('Extract Lead Data').item.json.lead_email,
    course_interest: $('Extract Lead Data').item.json.course_interest
  }
}];

